using System;using System.IO;using System.Reflection;using System.Linq;using System.Web.Script.Serialization;
class MonitorV520Tests {
 static int checks,failures;static void Check(bool ok,string name){checks++;if(!ok)failures++;Console.WriteLine((ok?"PASS ":"FAIL ")+name);}
 [STAThread]static int Main(string[] args){try{var a=new TaskbarAppearance();var sample=new SystemSample{Utc=DateTime.UtcNow,Cpu=27.41,Gpu=4,MemoryUsed=14.83,MemoryTotal=32};Check(TaskbarPainter.Format(sample,"cpu",a)=="27.4%","default precision shows CPU fractions");Check(TaskbarPainter.Format(sample,"memory",a)=="46.3%","memory fractions no longer hidden by integer rounding");a.PercentDecimals=2;Check(TaskbarPainter.Format(sample,"cpu",a)=="27.41%","two decimal resource precision supported");a.PercentDecimals=0;Check(TaskbarPainter.Format(sample,"cpu",a)=="27%","integer resource precision remains available");a.PercentDecimals=3;bool invalid=false;try{a.Validate();}catch(ArgumentException){invalid=true;}Check(invalid,"invalid resource precision rejected");
 using(var monitor=new TaskbarMonitor()){var cfg=new MonitorConfig{Taskbar=true,RefreshMilliseconds=2000};sample.Utc=DateTime.UtcNow.AddMinutes(-1);monitor.Update(sample,cfg);Check(monitor.SampleIsStale&&monitor.DisplaySample==null,"expired sample hidden instead of frozen values");sample=new SystemSample{Utc=DateTime.UtcNow,Cpu=32.5,MemoryUsed=15,MemoryTotal=32};monitor.Update(sample,cfg);Check(!monitor.SampleIsStale&&monitor.DisplaySample.Cpu==32.5,"fresh readings resume automatically");monitor.Update(null,cfg);Check(monitor.DisplaySample==null,"sampling failure clears displayed resources");}
 using(var telemetry=new Telemetry()){var field=typeof(Telemetry).GetField("gpuReading",BindingFlags.Instance|BindingFlags.NonPublic);var reading=field.GetValue(telemetry);var type=reading.GetType();type.GetField("CheckedUtc").SetValue(reading,DateTime.UtcNow.AddMinutes(-1));type.GetField("Load").SetValue(reading,(double?)99.1234);type.GetField("State").SetValue(reading,"NVIDIA驱动");var s=telemetry.Sample(25,8,32);Check(s.Gpu!=99.1234,"expired GPU cache cannot masquerade as fresh load");}
 }catch(Exception e){failures++;Console.WriteLine(e);}Directory.CreateDirectory(args[0]);File.WriteAllText(Path.Combine(args[0],"v520-results.json"),new JavaScriptSerializer().Serialize(new{checks,failures}));return failures==0?0:1;}
}
